diff --git a/js/common/smRuleLayers.js b/js/common/smRuleLayers.js
index 31d6c7f7..092c3157 100644
--- a/js/common/smRuleLayers.js
+++ b/js/common/smRuleLayers.js
@@ -53,6 +53,7 @@ var LAYERS = {
     'park-reset': 'L1',
     // L2 verdict — merge/fail/arm/sweep on heads that did NOT move this tick.
     'merge-validated': 'L2',
+    'merge-validated-guest': 'L2',
     'fail-validation': 'L2',
     'rework-on-red-gate-unlatched': 'L2',
     'rework-on-validation-failed': 'L2',
diff --git a/js/factoryState.js b/js/factoryState.js
index e4267fda..1c08b49c 100644
--- a/js/factoryState.js
+++ b/js/factoryState.js
@@ -727,6 +727,14 @@ function applyMutexSnapshot(state, input) {
     if (input.mutex) state.mutex = normalizeMutexSnapshot(input.mutex);
 }

+// gh-113 AC3 — the guest dead-zone block rides the snapshot verbatim (the
+// smAgent side already merged the per-PR first-seen carry over
+// input.prev.deadZone); absent on both sides ⇒ the key stays absent, the
+// schema never changes.
+function applyDeadZoneSnapshot(state, input) {
+    if (input.deadZone) state.deadZone = input.deadZone;
+}
+
 // gh-816 — per-head run verdicts (citation integrity). The runs list is
 // repo-wide and newest-first; classification is explicit (same idiom as
 // syncValidationChecks/failedRunLinksLine) because the list is shared with
@@ -927,6 +935,7 @@ function buildFactoryState(input) {
     // key when pricing is off/absent/malformed: the board renders tokens-only.
     if (costs) state.costs = costs;
     applyMutexSnapshot(state, input);
+    applyDeadZoneSnapshot(state, input);
     return state;
 }

diff --git a/js/smAgent.js b/js/smAgent.js
index 6a14bb86..7545ee94 100644
--- a/js/smAgent.js
+++ b/js/smAgent.js
@@ -185,11 +185,15 @@ var triggerFailuresModule = require('./common/triggerFailures.js');
 // label/probe-cadence config readers and the dispatch-lane exclusion
 // predicate. Pure module; the legs and the probe agent wire transport.
 var quotaBreakerModule = require('./common/quotaCircuitBreaker.js');
-// gh-1075 (hoisted, never lazy — the gh-823 pack-require rule): the
-// fork-PR dispatch contract — a cross-repo PR reroutes onto the base
+// gh-1075 (hoisted, never lazy — the gh-823 pack-require rule): the fork-PR dispatch contract — a cross-repo PR reroutes onto the base
 // machine ref with a refs/pull/<N>/head checkout plan (AC1) and its
 // no-ref liveness oracle is the pull-ref probe (AC2/AC3).
 var forkDispatchModule = require('./common/forkDispatch.js');
+// gh-113 (hoisted, never lazy — the gh-823 pack-require rule): the guest
+// validation path — the pure half of the guest-PR dead-zone fixes (the
