function _ghOverrideMergeState(pr, ms, resolveBranchHead) {
    if (pr.mergeable === false) return 'DIRTY';
    if (pr.base && pr.base.ref) {
        var head = resolveBranchHead(pr.base.ref);
        if (head) {
            if (pr.base.sha !== head) return 'BEHIND';
